window.RP_SESSION={"id":"S-c4f6910396c1","messages":[{"id":"RP-III-0008551","time":"2026-01-18T11:03:00+09:00","room":"RP III","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 린... 미안해... \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-III-0008552","time":"2026-01-18T11:14:00+09:00","room":"RP III","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 린, 나 안 버릴거지? 내가 미쳤다고 생각하지 않을거지? 날 두고 떠나지 마. 린... \"\n\n엘타리온은 굉장한 악몽을 꾸는듯이 잠꼬대를 하며 운다. 울부짖는다. 린은 그런 엘타리온을 침대 옆에서 안쓰럽게 처다본다. 룸메이트인 폴라리스한테는 이 무슨 민폐인지. 그렇게 늦잠을 잔 엘타리온은 깨어나서는 울면서 린에게 안긴다.\n\n\" 미안해, 린. 날... 날 용서해 줘. 내가 미쳤나봐. 너 없이는 살 수가 없는데, 내가 어떻게 널... 미안해, 린... \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-III-0008553","time":"2026-01-18T11:16:00+09:00","room":"RP III","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엘타리온은 린이 마치 자신은 아무것도 당하지 않은 것 처럼 같이 사과하는 것을 들었다. 아무런 변명도 섞이지 않은. 그저 여전히 너를 사랑하노라는 가족다운 사과. 둘은 그렇게 서로 부둥켜안고 한참을 운다. 폴라리스, 미안!","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-III-0008554","time":"2026-01-18T11:18:00+09:00","room":"RP III","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"왜 미안하는거죠?","characters":[]},{"id":"RP-III-0008555","time":"2026-01-18T11:22:00+09:00","room":"RP III","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"룸메인데 어제 밤부터 아침까지 쉬지 않고 온갖 시끄러운 소리란 소리는 다 내서요...","characters":["P-cf2651679b0b","P-cf90597a7c66"]}]};
